```python
def parse_duration(s: str) -> int:
    """
    Convert a duration string with optional hours, minutes, and seconds parts
    into a total number of seconds. Raise ValueError if the string is invalid.

    :param s: Duration string (e.g., "1h30m15s", "45m", "2h5s")
    :return: Total duration in seconds
    """
    if not s:
        raise ValueError("Empty string is not a valid duration.")

    total_seconds = 0
    remaining = s
    expected_order = ['h', 'm', 's']  # Expected order of parts

    for unit in expected_order:
        if remaining and remaining[0].isdigit():
            idx = remaining.find(unit)
            if idx == -1:
                continue  # Skip if unit is missing
            try:
                value = int(remaining[:idx])
                total_seconds += value * {'h': 3600, 'm': 60, 's': 1}[unit]
                remaining = remaining[idx+1:]
            except ValueError:
                raise ValueError(f"Invalid format for {unit} part.")
        elif remaining and remaining[0] == unit:
            raise ValueError(f"Unexpected {unit} without preceding number.")

    if remaining:
        raise ValueError("Invalid characters or format in the duration string.")

    return total_seconds
```

```python
def count_n_queens(n: int) -> int:
    """
    Returns the number of ways to place `n` queens on an n-by-n chessboard
    so that no two queens share a row, column, or diagonal using backtracking.

    :param n: The size of the chessboard and the number of queens.
    :return: The number of valid configurations.
    :raises ValueError: If `n` is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1

    def is_safe(board, row, col):
        """Check if placing a queen at (row, col) is safe."""
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == abs(i - row):
                return False
        return True

    def backtrack(row, board):
        """Recursively try to place queens row by row."""
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                count += backtrack(row + 1, board)
        return count

    return backtrack(0, [0] * n)
```

```python
def valid_brackets(s: str) -> bool:
    """Return True if all (), [], and {} brackets in s are correctly matched and nested."""
    pairs = {")": "(", "]": "[", "}": "{"}
    opening = set(pairs.values())
    stack = []

    for char in s:
        if char in opening:
            # Track opening brackets until their matching closers appear.
            stack.append(char)
        elif char in pairs:
            # A closing bracket must match the most recent opening bracket.
            if not stack or stack.pop() != pairs[char]:
                return False

    # Valid only if no opening brackets remain unmatched.
    return not stack
```

```python
def flatten(nested: list) -> list:
    """Return a new flat list of all non-list elements in left-to-right order."""
    flat = []
    stack = [iter(nested)]

    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            # Finished the current list; return to its parent.
            stack.pop()
            continue

        if type(item) is list:
            # Descend into lists only; keep tuples, strings, etc. as values.
            stack.append(iter(item))
        else:
            flat.append(item)

    return flat
```

```python
def leftmost_index(arr: list[int], target: int) -> int:
    """Return the index of the first occurrence of target in sorted arr, or -1."""
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            result = mid          # Record match and keep searching left
            right = mid - 1
        elif arr[mid] < target:
            left = mid + 1        # Target must be to the right
        else:
            right = mid - 1       # Target must be to the left

    return result
```

```python
def longest_common_subsequence(a: str, b: str) -> int:
    """Return the length of the longest common subsequence of strings a and b.

    Uses dynamic programming with O(min(len(a), len(b))) extra memory.
    """
    # Use the shorter string for the DP row to minimize memory usage.
    if len(a) < len(b):
        short, long = a, b
    else:
        short, long = b, a

    dp = [0] * (len(short) + 1)

    for ch_long in long:
        # prev holds the diagonal value from the previous row: dp[j - 1].
        prev = 0
        for j, ch_short in enumerate(short, start=1):
            temp = dp[j]
            if ch_long == ch_short:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp

    return dp[-1]
```

```python
import heapq


def shortest_paths(graph: dict[str, list[tuple[str, int]]], source: str) -> dict[str, int]:
    """Return shortest-path distances from source using Dijkstra's algorithm."""
    distances: dict[str, int] = {source: 0}
    heap: list[tuple[int, str]] = [(0, source)]

    while heap:
        current_dist, node = heapq.heappop(heap)

        # Skip stale heap entries that are no longer the best known distance.
        if current_dist != distances[node]:
            continue

        # Use an empty list for nodes that appear only as neighbors.
        for neighbor, weight in graph.get(node, []):
            new_dist = current_dist + weight

            # Relax the edge if a shorter path to the neighbor is found.
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))

    return distances
```

```python
def fizzbuzz(n: int) -> list[str]:
    """Return FizzBuzz list for 1 to n (or [] if n < 1)."""
    if n < 1:
        return []  # empty for invalid input
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")  # multiple of both
        elif i % 3 == 0:
            result.append("Fizz")  # multiple of 3 only
        elif i % 5 == 0:
            result.append("Buzz")  # multiple of 5 only
        else:
            result.append(str(i))  # plain number
    return result
```

```python
def sieve_primes(n: int) -> list[int]:
    """Return all primes <= n using the Sieve of Eratosthenes."""
    if n < 2:
        return []  # no primes below 2
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n+1, i):
                is_prime[j] = False  # mark multiples
    return [i for i in range(n+1) if is_prime[i]]
```

```python
def flatten(nested: list) -> list:
    """Return a flat list of all non-list elements from nested, left-to-right."""
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))  # recurse on nested list
        else:
            result.append(item)           # keep non-list as single element
    return result
```

```python
def rotate_matrix(matrix: list[list[int]]) -> list[list[int]]:
    """Rotate an n x n matrix 90 degrees clockwise, returning a new matrix."""
    if not matrix:
        return []
    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            # new row is old column, new column is n-1 minus old row
            result[j][n - 1 - i] = matrix[i][j]
    return result
```

```python
def leftmost_index(arr: list[int], target: int) -> int:
    """Return the leftmost index of target in sorted arr, or -1 if absent."""
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] < target:
            low = mid + 1  # search right half
        else:
            high = mid - 1  # search left half (including mid)
    if low < len(arr) and arr[low] == target:
        return low
    return -1
```

```python
def roman_to_int(s: str) -> int:
    """Convert valid Roman numeral (1-3999) to integer using standard and subtractive notation."""
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    res = 0
    for i in range(len(s)):
        # subtract if current value smaller than next (subtractive pair)
        if i + 1 < len(s) and values[s[i]] < values[s[i + 1]]:
            res -= values[s[i]]
        else:
            res += values[s[i]]
    return res
```

```python
def max_subarray_sum(nums: list[int]) -> int:
    """Return max sum of any contiguous subarray using Kadane's algorithm."""
    if not nums:
        raise ValueError("nums cannot be empty")
    max_current = max_global = nums[0]
    for num in nums[1:]:
        max_current = max(num, max_current + num)  # extend or start new
        if max_current > max_global:
            max_global = max_current
    return max_global
```

```python
def longest_common_subsequence(a: str, b: str) -> int:
    """Return length of longest common subsequence of a and b."""
    if len(a) > len(b):
        a, b = b, a  # ensure len(a) <= len(b) for O(min) space
    m, n = len(a), len(b)
    prev = [0] * (m + 1)
    curr = [0] * (m + 1)
    for j in range(1, n + 1):
        for i in range(1, m + 1):
            if a[i-1] == b[j-1]:
                curr[i] = prev[i-1] + 1
            else:
                curr[i] = max(prev[i], curr[i-1])
        prev, curr = curr, prev  # reuse arrays, O(min(len(a), len(b))) space
    return prev[m]
```

```python
def edit_distance(a: str, b: str) -> int:
    """Return the Levenshtein edit distance between strings a and b."""
    m, n = len(a), len(b)
    # DP table: dp[i][j] = distance for a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i  # deletions
    for j in range(n + 1):
        dp[0][j] = j  # insertions
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],   # delete
                                   dp[i][j-1],   # insert
                                   dp[i-1][j-1]) # substitute
    return dp[m][n]
```

```python
import heapq

def shortest_paths(graph: dict[str, list[tuple[str, int]]], source: str) -> dict[str, int]:
    """Compute shortest path distances from source using Dijkstra's algorithm."""
    # Collect all nodes including those appearing only as neighbors
    nodes = set(graph.keys())
    for neighbors in graph.values():
        for neigh, _ in neighbors:
            nodes.add(neigh)
    # Initialize distances
    dist = {node: float('inf') for node in nodes}
    dist[source] = 0
    # Priority queue for Dijkstra
    pq = []
    heapq.heappush(pq, (0, source))
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        if u in graph:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))
    # Return only reachable nodes
    return {k: v for k, v in dist.items() if v < float('inf')}
```

```python
def count_n_queens(n: int) -> int:
    """Count solutions to n-queens using backtracking."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    def backtrack(row, cols, diag1, diag2):
        if row == n:
            return 1  # found valid placement
        count = 0
        for col in range(n):
            if col not in cols and (row - col) not in diag1 and (row + col) not in diag2:
                cols.add(col)
                diag1.add(row - col)
                diag2.add(row + col)
                count += backtrack(row + 1, cols, diag1, diag2)
                cols.remove(col)
                diag1.remove(row - col)
                diag2.remove(row + col)
        return count
    return backtrack(0, set(), set(), set())
```
